const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Northern Tablelands, NSW, Australia
  const geometry = ee.Geometry.Point([151.5, -30.5]).buffer(50000); // 50km radius

  // 2. Define date range
  const startDate = '2025-08-02';
  const endDate = '2025-08-03';

  console.log('Searching for Sentinel-2 images...');

  // 3. Load Sentinel-2 Surface Reflectance with SCL band
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate(startDate, endDate);

  const imageCount = await collection.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('No Sentinel-2 images found for the specified date and location.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Use the first available image
  const image = collection.first();
  const scl = image.select('SCL');

  // 5. Define pixel classifications
  // SCL classes: 8=Cloud medium probability, 9=Cloud high probability, 10=Thin cirrus, 11=Snow/Ice
  const snowMask = scl.eq(11);
  const cloudMask = scl.eq(8).or(scl.eq(9)).or(scl.eq(10));

  // 6. Count pixels
  const snowCount = await snowMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('SCL').getInfo();

  const cloudCount = await cloudMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('SCL').getInfo();

  const totalPixels = await scl.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('SCL').getInfo();

  console.log(`Total pixels analyzed: ${totalPixels}`);
  console.log(`Snow pixels: ${snowCount}`);
  console.log(`Cloud pixels: ${cloudCount}`);

  // 7. Validation
  if (totalPixels === 0) {
    console.log('No valid pixels in the analysis area.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (snowCount === null || cloudCount === null) {
    console.log('Calculation failed - null values returned.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Determine answer
  if (snowCount > 0 && cloudCount === 0) {
    console.log('Result: Snow present, no clouds detected.');
    console.log('<answer>A</answer>');
  } else {
    console.log(`Result: Clouds present (${cloudCount} pixels) or no snow (${snowCount} pixels).`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
